content:
:root {
  --primary-color: #4f46e5;
  --primary-hover: #4338ca;
  --danger-color: #ef4444;
  --danger-hover: #dc2626;
  --bg-color: #f8fafc;
  --card-bg: #ffffff;
  --text-main: #1e293b;
  --text-muted: #64748b;
  --border-color: #e2e8f0;
  --radius: 12px;
  --shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, sans-serif;
}

body {
  background-color: var(--bg-color);
  color: var(--text-main);
  min-height: 100vh;
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 16px;
}

.app-container {
  width: 100%;
  max-width: 480px;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.calculator-card {
  background-color: var(--card-bg);
  border-radius: var(--radius);
  padding: 24px;
  box-shadow: var(--shadow);
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.title {
  font-size: 1.5rem;
  font-weight: 700;
  text-align: center;
  color: var(--text-main);
  margin-bottom: 4px;
}

.input-group {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.label {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--text-muted);
}

.input {
  width: 100%;
  padding: 10px 14px;
  font-size: 1rem;
  border: 1px solid var(--border-color);
  border-radius: 8px;
  outline: none;
  transition: border-color 0.2s, box-shadow 0.2s;
}

.input:focus {
  border-color: var(--primary-color);
  box-shadow: 0 0 0 3px rgba(79, 70, 229, 0.15);
}

.input.error {
  border-color: var(--danger-color);
}

.input.error:focus {
  box-shadow: 0 0 0 3px rgba(239, 68, 68, 0.15);
}

.error-message {
  font-size: 0.75rem;
  color: var(--danger-color);
  margin-top: 2px;
}

.btn-primary {
  background-color: var(--primary-color);
  color: #ffffff;
  border: none;
  border-radius: 8px;
  padding: 12px;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  transition: background-color 0.2s;
  width: 100%;
  margin-top: 8px;
}

.btn-primary:hover {
  background-color: var(--primary-hover);
}

.btn-danger {
  background-color: transparent;
  color: var(--danger-color);
  border: 1px solid var(--danger-color);
  border-radius: 6px;
  padding: 4px 8px;
  font-size: 0.75rem;
  font-weight: 600;
  cursor: pointer;
  transition: background-color 0.2s, color 0.2s;
}

.btn-danger:hover {
  background-color: var(--danger-color);
  color: #ffffff;
}

.result-card {
  background: linear-gradient(135deg, #f0fdf4 0%, #dcfce7 100%);
  border: 1px solid #bbf7d0;
  border-radius: var(--radius);
  padding: 20px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  text-align: center;
}

.badge {
  display: inline-block;
  padding: 4px 12px;
  font-size: 0.75rem;
  font-weight: 700;
  border-radius: 9999px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  background-color: #22c55e;
  color: #ffffff;
}

.value {
  font-size: 2.25rem;
  font-weight: 800;
  color: var(--text-main);
}

.category {
  font-size: 1rem;
  font-weight: 600;
  color: var(--text-muted);
}

.history-section {
  background-color: var(--card-bg);
  border-radius: var(--radius);
  padding: 20px;
  box-shadow: var(--shadow);
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.history-section h3 {
  font-size: 1.1rem;
  font-weight: 600;
  color: var(--text-main);
  border-bottom: 1px solid var(--border-color);
  padding-bottom: 8px;
}

.history-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 8px;
  max-height: 200px;
  overflow-y: auto;
}

.history-list li {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 8px 12px;
  background-color: var(--bg-color);
  border-radius: 6px;
  font-size: 0.875rem;
  gap: 8px;
}

@media (max-width: 480px) {
  body {
    padding: 12px;
    align-items: flex-start;
  }

  .calculator-card, .history-section, .result-card {
    padding: 16px;
  }

  .value {
    font-size: 1.85rem;
  }
}

import { useState, useEffect, type FormEvent } from 'react';
import './index.css';

interface HistoryItem {
  id: string;
  date: string;
  height: number;
  weight: number;
  bmi: number;
  category: string;
}

export default function App() {
  const [height, setHeight] = useState<string>('170');
  const [weight, setWeight] = useState<string>('60');
  const [history, setHistory] = useState<HistoryItem[]>(() => {
    const saved = localStorage.getItem('bmi_history');
    return saved ? JSON.parse(saved) : [];
  });

  useEffect(() => {
    localStorage.setItem('bmi_history', JSON.stringify(history));
  }, [history]);

  const h = parseFloat(height);
  const w = parseFloat(weight);

  const isHeightValid = !isNaN(h) && h > 0;
  const isWeightValid = !isNaN(w) && w > 0;
  const isValid = isHeightValid && isWeightValid;

  const bmi = isValid ? Number((w / Math.pow(h / 100, 2)).toFixed(1)) : 0;

  const getCategory = (val: number) => {
    if (val < 18.5) return '低体重（やせ）';
    if (val < 25) return '普通体重';
    if (val < 30) return '肥満（1度）';
    if (val < 35) return '肥満（2度）';
    if (val < 40) return '肥満（3度）';
    return '肥満（4度）';
  };

  const category = isValid ? getCategory(bmi) : '';
  const idealWeight = isValid ? Number((22 * Math.pow(h / 100, 2)).toFixed(1)) : 0;

  const getResultCardStyle = (val: number) => {
    if (val < 18.5) {
      return { background: 'linear-gradient(135deg, #e0f2fe 0%, #bae6fd 100%)', borderColor: '#7dd3fc' };
    } else if (val < 25) {
      return { background: 'linear-gradient(135deg, #f0fdf4 0%, #dcfce7 100%)', borderColor: '#bbf7d0' };
    } else {
      return { background: 'linear-gradient(135deg, #fef2f2 0%, #fee2e2 100%)', borderColor: '#fecaca' };
    }
  };

  const handleCalculate = (e: FormEvent) => {
    e.preventDefault();
    if (!isValid) return;

    const newItem: HistoryItem = {
      id: Date.now().toString(),
      date: new Date().toLocaleDateString() + ' ' + new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
      height: h,
      weight: w,
      bmi,
      category,
    };

    setHistory([newItem, ...history]);
  };

  const handleDeleteItem = (id: string) => {
    setHistory(history.filter((item) => item.id !== id));
  };

  const handleClearHistory = () => {
    setHistory([]);
  };

  return (
    <div className="app-container">
      <div className="calculator-card">
        <h1 className="title">BMI計算ツール</h1>
        <form onSubmit={handleCalculate} style={{ display: 'flex', flexDirection: 'column', gap: '16px' }}>
          <div className="input-group">
            <label className="label">身長 (cm)</label>
            <input
              type="number"
              step="0.1"
              className="input"
              value={height}
              onChange={(e) => setHeight(e.target.value)}
              placeholder="例: 170"
            />
          </div>
          <div className="input-group">
            <label className="label">体重 (kg)</label>
            <input
              type="number"
              step="0.1"
              className="input"
              value={weight}
              onChange={(e) => setWeight(e.target.value)}
              placeholder="例: 60"
            />
          </div>
          {!isValid && (
            <p style={{ fontSize: '0.875rem', color: '#ef4444', margin: '-4px 0 0 0' }}>
              有効な身長と体重（0より大きい数値）を入力してください。
            </p>
          )}
          <button type="submit" className="btn-primary" disabled={!isValid}>計算して履歴に追加</button>
        </form>
      </div>

      {isValid && (
        <div className="result-card" style={getResultCardStyle(bmi)}>
          <span className="badge">{category}</span>
          <div className="value">{bmi}</div>
          <div className="category">適正体重: {idealWeight} kg</div>
        </div>
      )}

      <div className="history-section">
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', borderBottom: '1px solid var(--border-color)', paddingBottom: '8px' }}>
          <h3 style={{ borderBottom: 'none', paddingBottom: 0 }}>計算履歴</h3>
          {history.length > 0 && (
            <button
              type="button"
              onClick={handleClearHistory}
              style={{
                background: 'transparent',
                border: 'none',
                color: '#ef4444',
                fontSize: '0.8125rem',
                cursor: 'pointer',
                fontWeight: 600,
              }}
            >
              すべてクリア
            </button>
          )}
        </div>
        {history.length === 0 ? (
          <p style={{ fontSize: '0.875rem', color: 'var(--text-muted)' }}>履歴はまだありません</p>
        ) : (
          <ul className="history-list">
            {history.map((item) => (
              <li key={item.id}>
                <span>{item.date} ({item.height}cm / {item.weight}kg)</span>
                <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                  <strong>BMI: {item.bmi} ({item.category})</strong>
                  <button
                    type="button"
                    onClick={() => handleDeleteItem(item.id)}
                    style={{
                      background: '#fee2e2',
                      color: '#991b1b',
                      border: 'none',
                      borderRadius: '4px',
                      padding: '2px 6px',
                      fontSize: '0.75rem',
                      cursor: 'pointer',
                    }}
                  >
                    削除
                  </button>
                </div>
              </li>
            ))}
          </ul>
        )}
      </div>
    </div>
  );
}
